#!/usr/bin/env bash
# Synthetic task core contracts and lifecycle. No provider calls.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
. "$root/scripts/lib/node-test-files.sh"
export CI=1 OMP_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1
out="$(mktemp -d "${TMPDIR:-/tmp}/didi-tasks.XXXXXX")"
trap 'rm -rf "$out"' EXIT
cd "$out"
"$root/server/node_modules/.bin/tsc" --types node --typeRoots "$root/server/node_modules/@types" --target ES2023 --module NodeNext --moduleResolution NodeNext --strict --noUncheckedIndexedAccess --exactOptionalPropertyTypes --skipLibCheck --esModuleInterop --rootDir "$root/server" --outDir "$out" "$root/server/test/canary-live-sequence.test.ts" "$root/server/test/canary-receipt.test.ts" "$root/server/test/task-vault.test.ts" "$root/server/test/task-chat.test.ts" "$root/server/test/task-call.test.ts" "$root/server/test/chat-tools.test.ts" "$root/server/test/live-dead-air.test.ts" "$root/server/test/heard-silence.test.ts" "$root/server/test/live-rebuild-sweep.test.ts" "$root/server/test/voice-replay.test.ts" "$root/server/test/open-actions.test.ts" "$root/server/test/mattermost-connector.test.ts" "$root/server/test/google-connector.test.ts" "$root/server/test/tools-admission.test.ts" "$root/server/test/vault-write.test.ts" "$root/server/test/wire-envelope.test.ts" "$root/server/test/calendar-read-contract.test.ts" "$root/server/test/loud-errors.test.ts" "$root/server/test/mattermost-attention.test.ts" "$root/server/test/mattermost-people.test.ts" "$root/server/test/task-sinks.test.ts" "$root/server/test/task-delivery.test.ts" "$root/server/test/tasks-contract.test.ts" "$root/server/test/tasks-mail-read.test.ts" "$root/server/test/tasks-lifecycle.test.ts" "$root/server/test/tasks-store.test.ts" "$root/server/test/live-shape.test.ts" "$root/server/test/tasks-failure-reason.test.ts" "$root/server/test/tasks-repeat.test.ts" "$root/server/test/tasks-company.test.ts" "$root/server/test/alarm-atomic.test.ts" "$root/server/test/tool-owner.test.ts" "$root/server/test/tasks-vault.test.ts" "$root/server/test/tasks-seams-1012.test.ts" "$root/server/test/tasks-seams-1013.test.ts" "$root/server/test/eval-sources.test.ts" "$root/server/test/task-tools-provider-shape.test.ts" "$root/server/test/supervised-stdout.test.ts"
printf '{"type":"module"}\n' > "$out/package.json"
ln -s "$root/server/node_modules" "$out/node_modules"
mkdir -p "$out/scripts" "$out/test/fixtures"
cp "$root/server/test/fixtures/google-error-contract-6ee466f0.json" "$root/server/test/fixtures/stdio-mattermost-child.mjs" "$root/server/test/fixtures/stdio-mattermost-people-child.mjs" "$root/server/test/fixtures/stdio-mattermost-attention-child.mjs" "$root/server/test/fixtures/mattermost-draft-tools-list.json" "$root/server/test/fixtures/google-tools-list.json" "$root/server/test/fixtures/stdio-mcp-child.mjs" "$root/server/test/fixtures/google-write-child.mjs" "$root/server/test/fixtures/host-compose-mattermost-child.mjs" "$root/server/test/fixtures/google-mcp-child.mjs" "$out/test/fixtures/"
mkdir -p "$out/scripts" "$out/test/fixtures" "$out/server/tasks"
cp "$root/server/tasks/instructions.ts" "$out/server/tasks/"
cp "$root/server/test/fixtures/google-error-contract-6ee466f0.json" "$root/server/test/fixtures/stdio-mattermost-child.mjs" "$root/server/test/fixtures/stdio-mattermost-people-child.mjs" "$root/server/test/fixtures/mattermost-draft-tools-list.json" "$root/server/test/fixtures/google-tools-list.json" "$root/server/test/fixtures/stdio-mcp-child.mjs" "$root/server/test/fixtures/google-write-child.mjs" "$root/server/test/fixtures/host-compose-mattermost-child.mjs" "$root/server/test/fixtures/google-mcp-child.mjs" "$out/test/fixtures/"
cp "$root/scripts/eval-worker-replay.mjs" "$out/scripts/"
DIDI_TEST_SOURCE_ROOT="$root/server/test" DIDI_TEST_BUILD_ROOT="$out" node_test_files --test-reporter=tap --test-timeout=15000 "$out/test/canary-live-sequence.test.js" "$out/test/canary-receipt.test.js" "$root/server/test/canary.test.mjs" "$out/test/task-vault.test.js" "$out/test/task-chat.test.js" "$out/test/task-call.test.js" "$out/test/chat-tools.test.js" "$out/test/live-dead-air.test.js" "$out/test/heard-silence.test.js" "$out/test/live-rebuild-sweep.test.js" "$out/test/voice-replay.test.js" "$out/test/open-actions.test.js" "$out/test/mattermost-connector.test.js" "$out/test/google-connector.test.js" "$out/test/tools-admission.test.js" "$out/test/vault-write.test.js" "$out/test/wire-envelope.test.js" "$out/test/calendar-read-contract.test.js" "$out/test/loud-errors.test.js" "$out/test/mattermost-attention.test.js" "$out/test/mattermost-people.test.js" "$out/test/task-sinks.test.js" "$out/test/task-delivery.test.js" "$out/test/tasks-contract.test.js" "$out/test/tasks-lifecycle.test.js" "$out/test/tasks-store.test.js" "$out/test/live-shape.test.js" "$out/test/tasks-mail-read.test.js" "$out/test/tasks-failure-reason.test.js" "$out/test/tasks-repeat.test.js" "$out/test/tasks-company.test.js" "$out/test/alarm-atomic.test.js" "$out/test/tool-owner.test.js" "$out/test/tasks-vault.test.js" "$out/test/tasks-seams-1012.test.js" "$out/test/tasks-seams-1013.test.js" "$out/test/task-tools-provider-shape.test.js" "$out/test/supervised-stdout.test.js"

cd "$root"
bash scripts/check-combined-tree.sh --selftest

# The worker guidance is pinned by the prompt unit and rendered-content contracts.
bash scripts/check-prompt.sh
